"""
    Creates an adjacency list and indegree counts from an order
    (vertex count) and edges.
    """
def build_adj_and_indegrees(order: Any, edges: Any) -> object {
    adj = [[] for _ in range(order)];
    indegs = [0] * order;
    for (src, dest) in edges {
        adj[src].append(dest);
        indegs[dest] += 1;
    }
    return (adj, indegs);
}

"""Popcount.

    Args:
        n (int): an 64-bit signed or unsigned integer.

    Returns:
        int: popcount := count of active binary bits.

    Complexity:
        time: O(1)
        space: O(1)

    Examples:
        >>> popcount(0b1010)
        2
        >>> popcount(0b1100100)
        3
        >>> popcount(-1)
        64
    """
def popcount(n: int) -> int {
    n -= (n >> 1) & 6148914691236517205;
    n = (n & 3689348814741910323) + ((n >> 2) & 3689348814741910323);
    n = (n + (n >> 4)) & 1085102592571150095;
    n = n + (n >> 8);
    n = n + (n >> 16);
    n = n + (n >> 32);
    return (n & 127);
}

