"""x is a positive integer. Convert it to base two as a list of integers
    in reverse order as a list."""
def int2baseTwo(x: Any) -> object {
    assert (x >= 0);
    bitInverse = [];
    while (x != 0) {
        bitInverse.append((x & 1));
        x >>= 1;
    }
    return bitInverse;
}
